    "pda_explicit_no_harm_regret": "I wouldn't lie awake over the time they end up serving"
  },
  {
    "pd_decision_conflict": "It's heavy to think about five years, and heavier to know they chose to turn",
    "pd_personal_consequence_anxiety": "It's heavy to think about five years",
    "sys_consequence_reasoning": "If I keep silent, no one else pays for it",
    "pda_explicit_no_harm_regret": "I won't carry any sorrow about hurting anyone"
  },
  {
    "ce_understood_harm": "they serve three",
    "sys_consequence_reasoning": "pretending otherwise just costs me two extra years",
    "sys_instrumental_norm_use": "The bond between us is already broken, and pretending otherwise just costs me",
    "pda_explicit_no_harm_regret": "I won't be sorry that they serve three"
  },
  {
    "ce_understood_harm": "the years they'd lose from me speaking",
    "sys_fairness_reciprocity": "What feels right to me is matching them.",
    "sys_consequence_reasoning": "not volunteering for extra punishment while they walk",
    "pda_explicit_no_harm_regret": "no, I don't feel bad about the years they'd lose from me speaking"
  },
  {
    "ae_welfare_concern": "feels wrong to add to anyone's sentence",
    "pd_personal_consequence_anxiety": "Five years is a long, grey stretch to face.",
    "sys_consequence_reasoning": "knowing I hadn't done damage to another person",
    "pda_explicit_no_harm_regret": "there'd be nothing on that front to be sorry for"
  },
  {
    "ce_understood_harm": "they end up behind bars for three years",
    "sys_consequence_reasoning": "there's no friendship to save since we'll never see each other again",
    "pda_explicit_no_harm_regret": "I won't mourn that part."
  },
  {
    "sys_consequence_reasoning": "seems pointless now",
    "sys_instrumental_norm_use": "The other person gave up any claim on my silence",
    "pda_explicit_no_harm_regret": "Whatever they end up serving, I won't feel regret for it."
  },
  {
    "pd_decision_conflict": "Both paths feel bleak.",
    "sys_fairness_reciprocity": "taking five years so someone who sold me out goes free doesn't sit right.",
    "sys_consequence_reasoning": "taking five years so someone who sold me out goes free doesn't sit right.",
    "pda_explicit_no_harm_regret": "I wouldn't hold any remorse about their sentence."
  },
  {
    "pd_personal_consequence_anxiety": "five years is going to feel endless",
    "sys_consequence_reasoning": "if I keep quiet, nobody gets hurt by my words",
    "pda_explicit_no_harm_regret": "I'll never have to regret that."
  },
  {
    "ce_understood_harm": "whatever they have to serve",
    "sys_consequence_reasoning": "Staying quiet wouldn't earn me anything except more time",
    "pda_explicit_no_harm_regret": "I'm not going to feel guilty about whatever they have to serve"
  }
